package org.apache.ibatis.cache.impl;

import java.util.HashMap;
import java.util.Map;

import org.apache.ibatis.cache.Cache;
import org.apache.ibatis.cache.CacheException;

/**
 * @author Clinton Begin
 */
// MyBatis 缓存机制中最基础、最核心的实现类
// PerpetualCache 的字面意思是“永久缓存”。它的作用非常纯粹：
// 基础存储介质：它是 MyBatis 一级缓存（Local Cache） 的默认实现，也是 二级缓存 的底层存储载体。
// 简单包装：它本质上是对 Java 原生 HashMap 的一个简单封装。
// 无策略缓存：它本身不包含任何缓存淘汰算法（如 LRU、FIFO）。除非手动调用 clear() 或 removeObject()，否则存入的数据会一直保留在内存中，直到对象被销毁。
public class PerpetualCache implements Cache {

  private final String id;

  private final Map<Object, Object> cache = new HashMap<>();

  public PerpetualCache(String id) {
    this.id = id;
  }

  @Override
  public String getId() {
    return id;
  }

  @Override
  public int getSize() {
    return cache.size();
  }

  @Override
  public void putObject(Object key, Object value) {
    cache.put(key, value);
  }

  @Override
  public Object getObject(Object key) {
    return cache.get(key);
  }

  @Override
  public Object removeObject(Object key) {
    return cache.remove(key);
  }

  @Override
  public void clear() {
    cache.clear();
  }

  @Override
  public boolean equals(Object o) {
    if (getId() == null) {
      throw new CacheException("Cache instances require an ID.");
    }
    if (this == o) {
      return true;
    }
    if (!(o instanceof Cache)) {
      return false;
    }

    Cache otherCache = (Cache) o;
    return getId().equals(otherCache.getId());
  }

  @Override
  public int hashCode() {
    if (getId() == null) {
      throw new CacheException("Cache instances require an ID.");
    }
    return getId().hashCode();
  }

}
